using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Arith.FibonacciAtomic.Observer;

internal sealed class ActualObserverAbsorbingNormalizationDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Arith/FibonacciAtomic/Observer/ActualObserverAbsorbingNormalization.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Static absent elimination preserves every nominal row, exactly filters actual ordered reports and caches, preserves all-history coarse action factorization, and dominates the original attained joint price.",
        H("Full Nominal Absorbing Absent Normalization"),
        Blocks(
            Paragraph(Text("Sources are the original nonempty ordered FreeMagma Bool trees. Allowed(N,U) means that U has at most N leaves, with N at least one. Every finite Boolean word remains a permitted address. Q_N consists of words of length at most N minus one. The four raw replies are alpha, beta, branch and absent; kappa identifies only branch with absent. Positive(U) is the original third-substitution image predicate. The immutable source is the same throughout each execution.")),
            Def("project", "Ordered literal projection", "project(N,h) filters h by membership of its literal address in Q_N. It retains the original raw replies, order and every repetition. The same operation is used on traces and on the installed ordered first-occurrence caches."),
            Def("retained", "Retained nominal rows", "A row is retained exactly when its action is a Boolean halt or a query at an address in Q_N."),
            Def("absentStep", "Static absent successor", "absentStep fixes every retained row and takes the original raw absent transition at every removed query row. It uses the installed table and N, without a source argument."),
            Def("scan", "Finite static first-exit scan", "scan(N,M,n,e) tests the first n rows of the static absent orbit, starting with e. It returns the first retained row, or none if the tested segment has no retained row."),
            Def("skip", "Complete nominal first-exit table", "skip scans exactly card(E) rows from each nominal e. The finite deterministic orbit bound ensures that every retained exit, if any exists, is found in this window. Thus none means that no finite iterate is retained, including at unreachable cyclic rows."),
            Def("normalized", "Independent native observer table", "normalized(N,M) is an Observer on exactly the original complete E with the same e0. Its decoder at every nominal e is literally project(N,M.decoder(e)), preserving address distinctness. At an entry with skip(e)=some s, its action is M.action(s) and its raw reply successor is M.transition(s,y). If skip(e)=none, its action is Halt(false) and every successor is e. Halt rows are interpreted absorbingly by the existing barStep. The static tables introduce no execution-time counter, source label, history argument or jump storage."),
            Describe.Lean(DescribeId.Create("absent-normalization-native-run"), DeclarationHandle.Create(Prefix + "normalize_run_from_actual_prefix"),
                H("Exact execution from every old actual prefix"), StatementSource.FromAuthor(RunFormula()), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every allowed original U, every Legal old observer, every actual old prefix ending at e and every old terminating suffix t from e, the independently installed normalized table has a native Run with precisely project(N,t), the same output bit, and final entry g with skip(g)=some f. Its decoded cache equals the ordered projection of the old final cache. The final entry g need not equal the old halt f. A removed request, including a cache hit, supplies raw absent by the original same-source cache truth and outside-address theorem. Filtering its exact cache update leaves the retained cache unchanged. A retained request has the same raw cached reply after projection. Induction constructs the new Run using its own query and halt constructors."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("absent-normalization-universal-pairs"), DeclarationHandle.Create(Prefix + "normalized_pair_transport"),
                H("Unrestricted paired-history transport"), StatementSource.FromAuthor(PairFormula()), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Assume only the old all-history FactorsThrough condition. Every pair generated by the normalized observer is generated by the old observer, and the normalized action also factors through kappa_hist on all finite raw histories. Old related rows have equal literal actions; simultaneous raw absent steps through removed queries remain related. Their first retained rows are related, or both scans have no exit. Retained raw reply pairs use the original PairReach step for every pair with equal kappa; normalized halts absorb at their entry rows. Impossible, raw-inconsistent, repeated, wrong-address and posthalt histories remain in scope. No equality between the old action on an arbitrary raw history and the new action on its filtered history is asserted."))), DescribeRole.Theorem),
            Def("charge", "Once-per-address real charge", "charge(tau,t) is the sum of tau(q) over the existing paid(t), the finite set of distinct literal addresses in t. Repeated reports and cached hits remain in the trace but do not incur a second address charge."),
            Def("Fee", "Native source execution fee", "For a terminating initial Run, Fee(M,tau,U) is charge(tau,t) on its unique trace. Run determinism makes this independent of the selected existence witness. Its default zero is used only when no terminating run exists; every allowed source of an Admissible observer has such a run."),
            Def("allowedSources", "Exact original finite source domain", "allowedSources(N) filters the existing boundedSources(N) enumeration by Allowed(N). The composition fibers and their existing finite instances show that every original tree with at most N leaves occurs; membership is equivalent to Allowed(N,U). Both labels and every ordered shape are retained, without a supplied coverage premise."),
            Def("maxFee", "Attained worst-source fee", "maxFee(N,M,tau) is the finite maximum of Fee over allowedSources(N), with default zero only for an empty domain. For N at least one, the domain contains a one-leaf source. Every allowed source fee is bounded above by this maximum, and a source in that same domain attains it."),
            Def("J_N", "Full nominal joint price", "J_N(N,M,tau,c) equals c times card(E) plus maxFee(N,M,tau). It charges every nominal configuration, including unreachable rows and cycles. The domain and each source are the original ones; there is no interchange of maximization with a per-address sum."),
            Def("NormalizationContract", "Complete same-carrier normalization contract", "The contract requires the same initial row; an exact first-exit specification on every nominal row, with a first retained index less than card(E) and no earlier retained index; and the absorbing Halt(false) fallback at every no-exit row. Every nominal decoder is the literal ordered filter and a sublist of the old decoder. Every installed query belongs to Q_N. The new observer is Admissible, so every allowed actual prefix has an empty initial cache, raw same-source truth, exact hit or append update, correct finite termination and all-history coarse factorization."),
            Paragraph(Text("The contract gives both prefix directions. Every old actual prefix h at e has a new prefix project(N,h) at g with skip(g)=skip(e) and new decoder equal to the projection of M.decoder(e). Every new actual prefix at entry e lifts to an old actual prefix at that same entry, whose projection is the new history. Every old initial Run t to f with bit b yields a new initial Run project(N,t) to g with the same b, skip(g)=some f and the projected final cache; it also has t.length less than card(E). Conversely every new initial Run s to g with bit b has an old Run t to f with that same b, s=project(N,t), skip(g)=some f and the same projected final cache. These are actual-source relations, not arbitrary raw-history cache identities.")),
            Paragraph(Text("The contract also transports every unrestricted new PairReach into old PairReach and states exact allowedSources membership. For every real address price tau with tau(q) at least zero, it gives Fee(new,tau,U) at most Fee(old,tau,U) for every allowed U, an allowed source attaining each of the old and new maxima, and J_N(new) at most J_N(old) for every strictly positive nominal price c. Zero address prices are included. The paid set of a filtered trace is exactly the old paid set restricted to Q_N; nonnegative finite-sum domination proves the sourcewise inequality. Attainment on the exact finite original source domain then proves the joint inequality.")),
            Describe.Lean(DescribeId.Create("absent-normalization-complete-contract"), DeclarationHandle.Create(Prefix + "absent_normalization_contract"),
                H("Complete normalization for every original competitor"), StatementSource.FromAuthor(ContractFormula()), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Every original Admissible observer has the specified normalized Observer on the same E satisfying all clauses of NormalizationContract. The two prefix constructions establish legality at every allowed actual prefix. Native execution simulation preserves termination and the original Positive output. Universal pair transport supplies the separate all-history condition. The existing finite orbit theorem is applied both to the static absent successor and to the source-specific absorbing successor; a constructor induction identifies an old Run with that iterate and its first halt. No additional uniform fuel assumption is required. This is a redesign theorem: it does not preserve the removed requests of a fixed exact-trace compiler, assert equality to an original policy on every impossible history, establish the finite table minimum, or price address length, synthesis, elapsed time, physical memory or communication."))), DescribeRole.Theorem))));

    private static DocumentBlock Def(string name, string title, string prose) => Describe.Lean(
        DescribeId.Create("absent-normalization-" + name.Replace("_", "").ToLowerInvariant()), DeclarationHandle.Create(Prefix + name),
        H(title), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(prose))), DescribeRole.Definition);
    private static Formula V(string name) => F.Id(name);
    private static Formula Par(Formula f) => Seq(Open, f, Close);
    private static Formula Call(string name, params Formula[] args) => new Formula.Apply(Seq(Operatorname, Grp(V(name))), [.. args]);
    private static Formula EqOf(Formula a, Formula b) => Seq(a, Sp, Eq, Sp, b);
    private static Formula And(params Formula[] fs) => Seq(fs.Select((f, i) => i == 0 ? Par(f) : Seq(Sp, Land, Sp, Par(f))).ToArray());
    private static Formula Imp(Formula a, Formula b) => Seq(Par(a), Sp, Implies, Sp, Par(b));
    private static Formula All(string names, Formula type, Formula body) => Seq(Forall, Sp,
        Seq(names.Split(',').Select((n, i) => i == 0 ? V(n) : Seq(Comma, Sp, V(n))).ToArray()), Colon, Sp, type, Comma, Sp, Par(body));
    private static Formula Some(string names, Formula type, Formula body) => Seq(Exists, Sp,
        Seq(names.Split(',').Select((n, i) => i == 0 ? V(n) : Seq(Comma, Sp, V(n))).ToArray()), Colon, Sp, type, Comma, Sp, Par(body));
    private static Formula Observers(Formula body) => All("E", V("Type"), Seq(OpenBracket, Call("Fintype", V("E")), CloseBracket, Comma, Sp,
        All("N", V("Nat"), All("M", Call("Observer", V("E")), body))));
    private static Formula New => Call("normalized", V("N"), V("M"));
    private static Formula Project(Formula h) => Call("project", V("N"), h);
    private static Formula Decoder(Formula m, Formula e) => Call("decoder", m, e);
    private static Formula Run(Formula m, Formula t, Formula f) => Call("Run", m, V("U"), V("e"), t, f, V("b"));
    private static Formula RunFormula()
    {
        Formula conclusion = Some("g", V("E"), And(Run(New, Project(V("t")), V("g")),
            EqOf(Call("skip", V("N"), V("M"), V("g")), Call("some", V("f"))),
            EqOf(Project(Decoder(V("M"), V("g"))), Project(Decoder(V("M"), V("f"))))));
        Formula assumptions = And(Call("Allowed", V("N"), V("U")), Call("Legal", V("M"), V("U")),
            Call("ActualPrefix", V("M"), V("U"), V("e"), V("h")), Run(V("M"), V("t"), V("f")));
        return Disp(Observers(All("U", V("Source"), All("e,f", V("E"), All("h,t", V("RawHistory"),
            All("b", V("Bool"), Imp(assumptions, conclusion)))))));
    }
    private static Formula Through(Formula m) => Call("FactorsThrough", Call("historyAction", m), Seq(V("kappa"), Underscore, Grp(V("hist"))));
    private static Formula PairFormula() => Disp(Observers(Imp(Through(V("M")), And(
        All("e,f", V("E"), Imp(Call("PairReach", New, V("e"), V("f")), Call("PairReach", V("M"), V("e"), V("f")))), Through(New)))));
    private static Formula ContractFormula() => Disp(Observers(Imp(Call("Admissible", V("N"), V("M")),
        Some("H", Call("Observer", V("E")), And(EqOf(V("H"), New), Call("NormalizationContract", V("N"), V("M"), V("H")))))));
}
